import {publicLanding,authScreen} from './public.js';
import {ensureCreatorAccounts} from './creator.js';
import {seedData,roles,navigation,rubric} from './data.js';
import {escapeHTML as e,canAccess,approvedHours,visibleStudents,visibleLogs,visibleApplications,hoursBetween,validateUpload,csvText,parseCSV,applyToJob,reviewLog} from './domain.js';

const $=s=>document.querySelector(s), app=$('#app'), modal=$('#modal');
const STORAGE='menteelog.demo.v1', SESSION='menteelog.demo.session';
let storageIssue=false;
function load(){try{const saved=JSON.parse(localStorage.getItem(STORAGE));return saved?.version===1&&Array.isArray(saved.users)&&Array.isArray(saved.logs)?saved:seedData();}catch{return seedData();}}
let db=ensureCreatorAccounts(load()),session=null,view={search:'',filter:'All',course:'All',mode:'All'},authRole='Student',modalSubmit=null,modalOpener=null,modalUserId=null,toastTimer;
try{session=JSON.parse(sessionStorage.getItem(SESSION));}catch{}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify(db));}catch{storageIssue=true;toast('Browser storage is full or unavailable. Changes last only until this page closes.');}}
function currentUser(){if(!session||session.expires<Date.now())return null;return db.users.find(u=>u.id===session.id&&u.status==='Active')||null;}
function storeSession(user){session={id:user.id,expires:Date.now()+30*60*1000};try{sessionStorage.setItem(SESSION,JSON.stringify(session));}catch{toast('Session storage unavailable; this demo session will end when you reload.');}}
function logout(){session=null;try{sessionStorage.removeItem(SESSION);}catch{}modal.close();location.hash='/';render();}
function notify(userId,type,title,message){db.notifications.unshift({id:crypto.randomUUID(),userId,type,title,message,date:new Date().toISOString(),read:false});}
function audit(action){db.audit.unshift({id:crypto.randomUUID(),actor:currentUser()?.name||'Demo',action,date:new Date().toISOString()});db.audit=db.audit.slice(0,150);}
function toast(message){const el=$('#toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,5000);}
const initials=name=>String(name||'ML').split(' ').filter(Boolean).map(n=>n[0]).slice(0,2).join('').toUpperCase();
const student=id=>db.users.find(u=>u.id===id);
const job=id=>db.jobs.find(j=>j.id===id);
const date=value=>value?new Date(value.length===10?value+'T12:00:00':value).toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'}):'—';
const time=value=>value?new Date(value).toLocaleTimeString('en-PH',{hour:'numeric',minute:'2-digit'}):'—';
const today=()=>new Date().toLocaleDateString('en-CA');
const iconPaths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',briefcase:'M8 6V3h8v3 M3 7h18v14H3z M8 7v14 M16 7v14',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h6',folder:'M3 6h7l2 3h9v12H3z M3 6V3h7l2 3h8v3',clock:'M12 8v5l4 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z',alert:'m12 3 10 18H2z M12 9v5 M12 17v1',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M15 4a4 4 0 0 1 0 8 M22 21v-3a4 4 0 0 0-3-3.8 M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0',building:'M5 22V2h14v20 M2 22h20 M9 6h1 M14 6h1 M9 10h1 M14 10h1 M9 14h1 M14 14h1 M10 22v-4h4v4',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z m-5 10 3 3 7-7',chart:'M3 3v18h19 M7 16V9 M12 16V5 M17 16v-5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',search:'M20 20l-5-5 M17 9a7 7 0 1 1-14 0 7 7 0 0 1 14 0',arrow:'M4 12h16 m-6-6 6 6-6 6',check:'m5 12 4 4L20 5',plus:'M12 4v16 M4 12h16',close:'m6 6 12 12 M18 6 6 18',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',upload:'M12 16V3 m-5 5 5-5 5 5 M4 16v5h16v-5',pin:'M20 9c0 6-8 13-8 13S4 15 4 9a8 8 0 1 1 16 0 M15 9a3 3 0 1 1-6 0 3 3 0 0 1 6 0',calendar:'M3 5h18v17H3z M7 2v6 M17 2v6 M3 11h18',message:'M3 3h18v14H8l-5 5z M7 8h10 M7 12h7',target:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0 M12 11v2',menu:'M3 6h18 M3 12h18 M3 18h18',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',logout:'M9 3H3v18h6 M9 12h12 m-5-5 5 5-5 5'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.file}"/></svg>`;}
const brand=()=>'<a class="brand-link" href="#/" aria-label="MenteeLog home"><img class="logo" src="./assets/logo.svg" alt="MenteeLog"></a>';
function badge(value){const color=['Approved','Accepted','Active','Accredited','Resolved','Cleared','Completed'].includes(value)?'green':['Rejected','Flagged','High','Suspended'].includes(value)?'red':['Pending','Under_Review','Medium','Pending_Activation','Scheduled'].includes(value)?'amber':['Enrolled','Eligible'].includes(value)?'blue':'neutral';return `<span class="badge ${color}">${e(value?.replaceAll('_',' ')||'Draft')}</span>`;}
const button=(label,action,id='',style='secondary',ico='')=>`<button type="button" class="btn ${style}" data-action="${action}" data-id="${e(id)}">${ico?icon(ico):''}${label}</button>`;
const link=(label,page,style='secondary',ico='')=>`<a class="btn ${style}" href="#/${currentUser()?.role.toLowerCase()||'student'}/${page}">${ico?icon(ico):''}${label}</a>`;
const empty=(title,description='')=>`<div class="empty">${icon('folder')}<h3>${title}</h3><p class="mb0">${description}</p></div>`;
const stat=(title,value,sub,ico)=>`<div class="stat"><span class="stat-icon">${icon(ico)}</span><div><div class="stat-label">${title}</div><div class="stat-value">${value}</div><div class="stat-sub">${sub}</div></div></div>`;
const person=u=>`<div class="row"><span class="avatar square">${e(initials(u?.name))}</span><div><strong>${e(u?.name||'Unknown student')}</strong><small>${e(u?.course||u?.role||'')}</small></div></div>`;
const progress=(hours,required)=>`<div class="row"><progress class="progress" max="${required}" value="${Math.min(hours,required)}" aria-label="${hours} of ${required} hours"></progress><small>${Math.round(hours/required*100)}%</small></div>`;
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function tabs(values){return `<div class="tabs" role="group" aria-label="View filter">${values.map(t=>`<button class="tab ${view.filter===t?'active':''}" data-action="filter" data-id="${e(t)}" aria-pressed="${view.filter===t}">${e(t.replaceAll('_',' '))}</button>`).join('')}</div>`;}
function field(label,name,type='text',value='',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${e(value)}" ${extra}></div>`;}
function textarea(label,name,value='',extra='required'){return `<div class="field"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" maxlength="3000" ${extra}>${e(value)}</textarea></div>`;}
function select(label,name,options,value=''){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${e(v)}" ${v===value?'selected':''}>${e(l.replaceAll('_',' '))}</option>`;}).join('')}</select></div>`;}
function showModal(title,body,onSubmit,label='Save changes'){
  modalOpener=document.activeElement;modalSubmit=onSubmit;modalUserId=currentUser()?.id||null;
  modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${onSubmit?'<form id="modal-form">':''}${body}${onSubmit?`<p class="form-error" role="alert"></p><div class="form-actions">${button('Cancel','close')}<button class="btn" type="submit">${label}</button></div></form>`:''}</div>`;
  modal.showModal();
}
modal.addEventListener('close',()=>{modalSubmit=null;if(modalOpener?.isConnected)modalOpener.focus();});
function download(name,content,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function route(){const parts=location.hash.replace(/^#\/?/,'').split('/');return {role:parts[0],page:parts[1]||'dashboard'};}
function render(){
  const {role,page}=route();
  if(!role||role==='public'){app.innerHTML=landing();document.title='MenteeLog | Your OJT journey, connected';return;}
  if(['login','activate','reset'].includes(role)){app.innerHTML=authPage(role);document.title='MenteeLog | Authentication';return;}
  const user=currentUser();
  if(!user){location.hash='/login';return;}
  if(role!==user.role.toLowerCase()||!canAccess(user.role,page)){location.hash=`/${user.role.toLowerCase()}/dashboard`;toast('This page is not available in your portal.');return;}
  const title=navigation[user.role].find(n=>n[0]===page)?.[1]||({profile:'Profile & Settings',notifications:'Notifications',jobs:'Job Management',candidates:'Candidate Review',applications:'Application Review'}[page]);
  document.title=`${title} | MenteeLog`;
  const unread=db.notifications.filter(n=>n.userId===user.id&&!n.read).length;
  app.innerHTML=`<aside class="sidebar" id="sidebar">${brand()}<button class="icon-btn mobile-toggle" data-action="menu" aria-label="Close navigation">${icon('close')}</button><div class="portal-label">${user.role.toUpperCase()} PORTAL</div><nav aria-label="Main navigation">${navigation[user.role].map(([id,label,ico])=>`<a class="nav-link ${page===id?'active':''}" href="#/${role}/${id}" ${page===id?'aria-current="page"':''}>${icon(ico)}${label}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-person row"><span class="avatar">${e(initials(user.name))}</span><div><p>${e(user.name)}</p><small>${user.role==='Student'?'OJT Student':user.role==='Supervisor'?'Company Supervisor':'Faculty Coordinator'}</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="row"><button class="icon-btn mobile-toggle" data-action="menu" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button><div class="breadcrumb"><span>MenteeLog</span><span>›</span><strong>${title}</strong></div></div><div class="top-actions"><input class="top-search" id="global-search" aria-label="Search portal pages" placeholder="Search pages…" type="search"><button class="icon-btn" data-action="notifications" aria-label="Notifications, ${unread} unread">${icon('bell')}${unread?'<span class="notification-dot"></span>':''}</button><details class="profile-menu"><summary aria-label="Your account"><span class="avatar">${e(initials(user.name))}</span></summary><div class="profile-popover"><strong class="small">${e(user.name)}</strong><a href="#/${role}/profile">Profile & settings</a><button class="text-btn" data-action="logout">${icon('logout')} Sign out</button></div></details></div></header><main class="content" id="main" tabindex="-1">${pageContent(page,user)}</main></div>`;
}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${actions?`<div class="row wrap">${actions}</div>`:''}</div>`;}
function landing(){return publicLanding(route().role==='public'?route().page:'home',{brand,icon});}
function authPage(mode){return authScreen(mode,authRole,{brand,icon,field});}
function jobCard(j,publicPage=false){return `<article class="card job-card"><div class="row between"><span class="job-mark">${e(initials(j.company))}</span>${badge(j.mode)}</div><div><h3>${e(j.title)}</h3><span class="company">${e(j.company)}</span></div><div class="meta"><span>${icon('pin')} ${e(j.location)}</span><span>${icon('users')} ${e(j.courses.map(c=>c.replace('BS Computer Science','BSCS').replace('BS Information Technology','BSIT').replace('BS Computer Engineering','BSCpE')).join(' / '))}</span></div><div class="card-footer"><span class="small">${j.slots} slots available</span>${publicPage?'<a href="#/login" class="btn small">Explore role</a>':button('View details','job-detail',j.id,'small')}</div></article>`;}
function pageContent(page,u){return ({dashboard:dashboard,jobs:jobsPage,applications:applicationsPage,dtr:dtrPage,incidents:incidentsPage,appraisals:appraisalsPage,candidates:candidatesPage,hte:htePage,reports:reportsPage,users:usersPage,notifications:notificationsPage,profile:profilePage,documents:documentsPage}[page]||dashboard)(u);}
function notificationsMini(u){const notes=db.notifications.filter(n=>n.userId===u.id).slice(0,2);return `<section class="card dashboard-notices"><div class="card-title"><h2>Notifications</h2><button class="text-btn small" data-action="read-all">Mark all read</button></div>${notes.map(n=>`<div class="notification-card"><strong>${n.read?'':'• '}${e(n.title)}</strong><p>${e(n.message)}</p></div>`).join('')||'<p class="small muted">You’re all caught up.</p>'}<a class="text-btn full" href="#/${u.role.toLowerCase()}/notifications">View all notifications →</a></section>`;}
function dashboard(u){
 const students=visibleStudents(db,u),logs=visibleLogs(db,u),pending=logs.filter(l=>l.status==='Pending').length;
 if(u.role==='Student'){const hrs=approvedHours(db,u.id),a=db.applications.find(a=>a.studentId===u.id&&a.status==='Accepted'),j=a&&job(a.jobId),weekly=db.logs.filter(l=>l.studentId===u.id).slice(-5);return heading('Good morning, '+e(u.name.split(' ')[0])+'!',date(today())+' · '+e(u.company||'OJT Student'))+
 '<div class="grid-3">'+stat('OJT Hours Rendered',hrs+' / '+u.requiredHours+' Hours',Math.round(hrs/u.requiredHours*100)+'% completed','target')+stat('Current Status',db.shift?.studentId===u.id?'Clocked In':'Clocked Out',db.shift?.studentId===u.id?'Started at '+time(db.shift.clockIn):'Ready for your next shift','clock')+stat('Days Remaining',Math.max(0,Math.ceil((new Date(db.program.deadline)-Date.now())/86400000)),'Until OJT completion','calendar')+'</div><div class="student-dash-grid section-space"><section class="card"><div class="card-title"><div><h2>Weekly Hours Rendered</h2><p class="small">Your latest daily time records</p></div><span class="small">Total: '+weekly.reduce((sum,l)=>sum+l.hours,0)+'h</span></div><div class="bar-chart"><div class="chart-y"><span>12h</span><span>8h</span><span>4h</span><span>0h</span></div>'+weekly.map(l=>'<div class="bar-column"><svg viewBox="0 0 36 132" role="img" aria-label="'+l.hours+' hours"><rect x="0" y="'+(132-l.hours*11)+'" width="36" height="'+l.hours*11+'" rx="4"/></svg><span>'+new Date(l.date+'T12:00:00').toLocaleDateString('en-PH',{weekday:'short'})+'</span></div>').join('')+'</div></section>'+notificationsMini(u)+'</div><section class="card placement-summary section-space"><h2>Active OJT Placement</h2>'+(j?table(['Company','Role','Supervisor','Department','OJT Adviser'],['<tr><td>'+e(j.company)+'</td><td>'+e(j.title)+'</td><td>'+e(student(j.supervisorId)?.name||'Pending')+'</td><td>IT Department</td><td>Dr. Evelyn Ramos</td></tr>']):empty('No active placement','Browse accredited opportunities to begin.'))+'</section>';}
 if(u.role==='Supervisor')return heading('Supervisor Dashboard',e(u.company)+' · OJT Internship Program')+'<div class="grid-4">'+stat('Active Interns',students.length,'Currently assigned to you','users')+stat('Pending DTRs',pending,'Awaiting approval','clock')+stat('Evaluations Due',students.filter(s=>!db.appraisals.some(a=>a.studentId===s.id)).length,'Performance appraisals','star')+stat('Hours Approved',logs.filter(l=>l.status==='Approved').reduce((s,l)=>s+l.hours,0)+'h','Approved attendance records','chart')+'</div><div class="card sand dashboard-quick row wrap"><strong>Quick Actions:</strong>'+link('Review Pending DTRs','dtr','','check')+button('Add Intern Slot','job-edit','','secondary','plus')+'<span class="push-right">'+button('Send Emergency Alert','announcement','','secondary','alert')+'</span></div><section class="card sand supervisor-roster"><div class="card-title"><h2>Active Interns Overview</h2>'+link('Candidate Review','candidates','secondary small')+'</div>'+studentTable(students,u)+'</section>';
 const all=db.users.filter(s=>s.role==='Student'),placed=all.filter(s=>s.company),percent=Math.round(placed.length/Math.max(1,all.length)*100),active=db.htes.filter(h=>h.status==='Accredited').length;return heading('Coordinator Dashboard','College of Information Technology · OJT Management Overview')+'<div class="grid-4 stat-grid-bordered">'+stat('Total Students',all.length,'Enrolled this semester','users')+stat('Placed Students',placed.length,percent+'% placement rate','check')+stat('Accredited HTEs',active,'Active partner companies','building')+stat('Flagged Entries',db.logs.filter(l=>l.status==='Flagged').length,'Requires attention','alert')+'</div><div class="coordinator-dash-grid"><section class="card sand"><h2>Placement Breakdown</h2><div class="row"><div class="ring"><svg viewBox="0 0 132 132" aria-hidden="true"><circle class="track" cx="66" cy="66" r="55"/><circle class="value" cx="66" cy="66" r="55" pathLength="100" stroke-dasharray="'+percent+' 100"/></svg><span>'+percent+'%</span></div><div><p>Placed: '+placed.length+'</p><p>Unplaced: '+(all.length-placed.length)+'</p></div></div></section><section class="card sand"><h2>HTE Accreditation Status</h2>'+[['Active',active],['Pending',db.htes.filter(h=>h.status==='Pending').length],['Expiring Soon',db.htes.filter(h=>new Date(h.expiry)-Date.now()<60*86400000).length]].map(([label,n])=>'<p class="row between"><span>'+label+'</span><strong>'+n+'</strong></p>'+progress(n,Math.max(1,db.htes.length))).join('')+'<p class="small">Overall OJT Completion</p>'+progress(all.reduce((n,s)=>n+approvedHours(db,s.id),0),all.reduce((n,s)=>n+s.requiredHours,0))+'</section><section class="card sand"><h2>Real-time Activity Feed</h2>'+(db.audit.length?db.audit.slice(0,4).map(a=>'<div class="activity-item"><p>'+e(a.action)+'</p><small>'+date(a.date)+'</small></div>').join(''):'<p class="small">No recent changes. Placement, attendance, and governance activity will appear here.</p>')+'</section></div>';
}
function studentTable(students,u){return students.length?table(['Intern','Hours rendered','Progress','Status','Action'],students.map(s=>`<tr><td>${person(s)}</td><td>${approvedHours(db,s.id)} / ${s.requiredHours} hrs</td><td>${progress(approvedHours(db,s.id),s.requiredHours)}</td><td>${badge(s.badge)}</td><td>${button('View profile','student-detail',s.id,'secondary small')}</td></tr>`)):empty('No students in this view','Assigned students will appear here.');}
function searchToolbar(placeholder,extras=''){return `<form class="toolbar" id="search-form"><input type="search" name="search" aria-label="${placeholder}" placeholder="${placeholder}" value="${e(view.search)}"><button class="btn secondary" type="submit">${icon('search')} Search</button>${extras}</form>`;}
function matches(...texts){return texts.join(' ').toLowerCase().includes(view.search.toLowerCase());}
function jobsPage(u){const jobs=db.jobs.filter(j=>(u.role==='Student'?j.status==='Active':u.role==='Supervisor'?j.supervisorId===u.id:true)&&matches(j.title,j.company,j.location,j.skills)&&(view.filter==='All'||j.status===view.filter));return heading(u.role==='Student'?'OJT Placement Directory':u.role==='Supervisor'?'Slot Management':'Job Management',u.role==='Student'?'Discover accredited opportunities matched to your program and career goals.':'Manage internship openings and candidate applications.',u.role==='Student'?'':button('Post New Work','job-edit','','','plus'))+(u.role==='Student'?searchToolbar('Search companies, positions or location'):tabs(['All','Active','Draft','Closed']))+(u.role==='Student'?jobs.map(j=>'<article class="directory-card"><div class="row between"><div class="row"><span class="job-mark">'+e(initials(j.company))+'</span><div><h2>'+e(j.title)+'</h2><span>'+e(j.company)+'</span></div></div>'+badge('Accredited')+'</div><div class="meta-row"><span>'+icon('pin')+' '+e(j.location)+'</span><span>'+e(j.courses.join(' / '))+'</span><span>'+j.slots+' slots available</span></div><div class="skill-tags">'+j.skills.split(',').map(t=>'<span>'+e(t.trim())+'</span>').join('')+'</div><div class="row between details-row"><small>'+e(j.mode)+'</small>'+button('View Details','job-detail',j.id,'secondary small')+'</div>'+button(db.applications.some(a=>a.studentId===u.id&&a.jobId===j.id&&a.status!=='Rejected')?'View Application':'Apply Now','job-detail',j.id,'full')+'</article>').join(''):'<section class="card sand">'+table(['Position Title','Department','Applicants','Status','Actions'],jobs.map(j=>'<tr><td><strong>'+e(j.title)+'</strong><small>'+e(j.company)+'</small></td><td>IT Department</td><td>'+db.applications.filter(a=>a.jobId===j.id).length+'</td><td>'+badge(j.status)+'</td><td><div class="row">'+button('View','job-detail',j.id,'secondary small')+button('Edit','job-edit',j.id,'secondary small')+'</div></td></tr>'))+'</section><div class="mt16">'+link(u.role==='Coordinator'?'Candidate Tracking':'Application Review',u.role==='Coordinator'?'candidates':'applications','secondary')+'</div>');}
function applicationsPage(u){const apps=visibleApplications(db,u).filter(a=>(view.filter==='All'||a.status===view.filter)&&matches(student(a.studentId)?.name,job(a.jobId)?.title,job(a.jobId)?.company));return heading(u.role==='Student'?'My Applications Tracker':'Application Review',u.role==='Student'?'Track your internship applications and placement progress.':'Review and endorse your candidates.')+(u.role==='Student'?'':tabs(['All','Pending','Under_Review','Accepted','Rejected'])+searchToolbar('Search applications'))+(apps.length?apps.map(a=>{const j=job(a.jobId),level=a.status==='Accepted'?3:a.status==='Under_Review'?1:0;return '<section class="card application-card"><div class="row between"><div><h2>'+e(j?.company)+' — '+e(j?.title)+'</h2><small>Applied '+date(a.date)+(u.role==='Student'?'':' · '+e(student(a.studentId)?.name))+'</small></div>'+badge(a.status)+'</div><div class="application-path">'+['Submitted','Under Review','Interview','Accepted'].map((label,i)=>(i?'<span class="application-line"></span>':'')+'<div class="application-step '+(i<=level?'done':'')+'"><i></i><span>'+label+'</span></div>').join('')+'</div><div class="mt16">'+button(u.role==='Student'?'View Details':'Review Application','application-detail',a.id,'secondary small')+'</div></section>';}).join(''):empty('No applications in this view','Your application progress will appear here.'));}
function dtrPage(u){if(u.role==='Coordinator')return compliancePage(u);const logs=visibleLogs(db,u).filter(l=>(view.filter==='All'||l.status===view.filter)&&matches(student(l.studentId)?.name,l.date,l.task));const studentView=u.role==='Student',shift=db.shift?.studentId===u.id?db.shift:null;const hrs=approvedHours(db,u.id);return `${heading(studentView?'Daily Time Record Hub':u.role==='Supervisor'?'Attendance & DTR':'DTR Compliance',studentView?'Log your attendance and learning, then submit for supervisor review.':'Review attendance, task summaries, and entries requiring attention.',button('Export log summary','export-dtr','','secondary','download'))}${studentView?`<div class="grid-3">${stat('Current shift',shift?'Clocked in':'Not clocked in',shift?'Started '+time(shift.clockIn):'Start when your workday begins','clock')}${stat('Hours awaiting review',visibleLogs(db,u).filter(l=>['Pending','Flagged'].includes(l.status)).reduce((s,l)=>s+l.hours,0)+' hours','Pending and flagged entries','file')}${stat('Internship progress',hrs+' / '+u.requiredHours+' hrs','Approved hours only','target')}</div><div class="narrow-wide reference-dtr section-space"><div class="stack"><section class="card sand"><span class="eyebrow">TODAY · ${date(today())}</span><div class="timer" id="shift-timer">${shift?elapsed(shift.clockIn):'00:00:00'}</div><span class="small">${shift?'Your shift is in progress':'Ready when you are'}</span><div class="location-panel"><div class="reference-map" aria-label="Location capture illustration"></div>${icon('pin')}<p><strong>${shift?.gps?'Location captured':shift?'Location unavailable':'Optional location capture'}</strong></p><small class="muted">${shift?.gps?'Coordinates captured on this device. Verification requires the server.':'Your browser will request permission. A justification is required if location is unavailable.'}</small></div>${button(shift?'Clock out & submit':'Clock in','clock','','full',shift?'check':'clock')}</section><section class="card"><h2>Today’s task summary</h2><label class="small muted" for="draft">Your work, key learnings, and next steps</label><textarea id="draft" maxlength="3000" class="mt16" placeholder="What did you work on today?">${e(db.draft)}</textarea><small class="muted">Draft saved in this browser as you type.</small></section></div><div><section class="card"><h2>DTR history</h2>${tabs(['All','Pending','Approved','Flagged','Rejected'])}${dtrTable(logs,u)}</section></div></div>`:`${tabs(['All','Pending','Approved','Flagged','Rejected'])}${searchToolbar('Search intern, date, or task')}<section class="card">${dtrTable(logs,u)}</section>`}`;}
function compliancePage(u){const students=visibleStudents(db,u).filter(s=>matches(s.name,s.identifier,s.company)),logs=visibleLogs(db,u),flagged=logs.filter(l=>['Flagged','Rejected'].includes(l.status)),pending=logs.filter(l=>l.status==='Pending'),approved=logs.filter(l=>l.status==='Approved');return heading('DTR Compliance Monitor','Monitor daily time records, completion progress, and compliance risks across active interns.',button('Export Log Summary','export-dtr','','','download'))+'<div class="grid-4 stat-grid-bordered">'+stat('Total Deployed Students',students.filter(s=>s.company).length,'Active placements','users')+stat('Compliance Rate',Math.round(approved.length/Math.max(1,logs.length)*100)+'%','Approved attendance entries','check')+stat('Non-compliant',flagged.length,'Require intervention','alert')+stat('Pending Review',pending.length,'Awaiting supervisor review','clock')+'</div><section class="card sand section-space">'+searchToolbar('Search student, SR code or company')+'</section><section class="card sand section-space"><h2>Student Compliance Overview</h2>'+table(['Student Name','Program','HTE Company','Hours Progress','Status','Action'],students.map(s=>'<tr><td><strong>'+e(s.name)+'</strong></td><td>'+e(s.course)+'</td><td>'+e(s.company||'Unassigned')+'</td><td>'+progress(approvedHours(db,s.id),s.requiredHours)+'</td><td>'+badge(flagged.some(l=>l.studentId===s.id)?'Flagged':'Active')+'</td><td>'+button('View Details','student-detail',s.id,'secondary small')+'</td></tr>'))+'</section><section class="card sand section-space"><h2>Flagged Entries</h2>'+dtrTable(flagged,u)+'</section><section class="card section-space"><h2>Department Hours Log</h2><div class="report-bars">'+[...new Set(students.map(s=>s.course))].map(course=>{const cohort=students.filter(s=>s.course===course);return '<div><strong class="small">'+e(course)+'</strong>'+progress(cohort.reduce((n,s)=>n+approvedHours(db,s.id),0),Math.max(1,cohort.reduce((n,s)=>n+s.requiredHours,0)))+'</div>';}).join('')+'</div></section>';}

function elapsed(start){const seconds=Math.max(0,Math.floor((Date.now()-new Date(start))/1000));return [Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(v=>String(v).padStart(2,'0')).join(':');}
function dtrTable(logs,u){return logs.length?table([...(u.role==='Student'?[]:['Intern']),'Date','Clock In','Clock Out',...(u.role==='Student'?['Total']:['Task Summary']),'GPS','Status','Action'],logs.slice().reverse().map(l=>'<tr>'+(u.role==='Student'?'':'<td><strong>'+e(student(l.studentId)?.name)+'</strong></td>')+'<td>'+date(l.date)+'</td><td>'+time(l.clockIn)+'</td><td>'+time(l.clockOut)+'</td><td>'+(u.role==='Student'?l.hours.toFixed(2)+'h':'<span class="task-excerpt">'+e(l.task)+'</span>')+'</td><td>'+badge(l.gps?'Captured':'Unavailable')+'</td><td>'+badge(l.status)+'</td><td>'+button(u.role==='Supervisor'&&['Pending','Flagged'].includes(l.status)?'Review':u.role==='Student'&&['Flagged','Rejected'].includes(l.status)?'Justify':'View','log-detail',l.id,'secondary small')+'</td></tr>')):empty('No DTR entries here','Submitted attendance records will appear here.');}
function candidatesPage(u){const all=visibleStudents(db,u),list=all.filter(s=>matches(s.name,s.identifier,s.company,s.course)&&(view.filter==='All'||(view.filter==='Unplaced'?!s.company:view.filter==='Placed'?!!s.company:s.badge==='Cleared')));return heading(u.role==='Supervisor'?'Candidate Review & Roster':'Student Placement Overview','Track candidate assignments, training progress, and completion clearance.',(u.role==='Coordinator'?button('Bulk Import CSV','import-users','','secondary','upload'):'')+button('Export Roster','export-students','','secondary','download'))+tabs(['All','Placed','Unplaced','Cleared'])+'<div class="grid-4 stat-grid-bordered">'+stat('Total Students',all.length,'Current cohort','users')+stat('Placed',all.filter(s=>s.company).length,'Assigned to HTEs','building')+stat('Unassigned',all.filter(s=>!s.company).length,'Awaiting placement','clock')+stat('Cleared',all.filter(s=>s.badge==='Cleared').length,'Requirements complete','check')+'</div><section class="card sand section-space">'+searchToolbar('Search students, SR code or company')+table(['Student','Program','HTE Assignment','Hours Progress','Status','Actions'],list.map(s=>'<tr><td><strong>'+e(s.name)+'</strong><small>'+e(s.identifier)+'</small></td><td>'+e(s.course)+'</td><td>'+e(s.company||'Unassigned')+'</td><td>'+progress(approvedHours(db,s.id),s.requiredHours)+'</td><td>'+badge(s.badge)+'</td><td>'+button('View / Assign','student-detail',s.id,'secondary small')+'</td></tr>'))+'</section>'+(u.role==='Coordinator'?'<section class="card sand section-space"><h2>Unplaced Students — Action Required</h2>'+studentTable(all.filter(s=>!s.company),u)+'</section>':link('Application Review','applications','secondary'));}
function visibleIncidents(u){return db.incidents.filter(i=>u.role==='Coordinator'||(u.role==='Student'?i.studentId===u.id:i.supervisorId===u.id));}
function incidentsPage(u){const all=visibleIncidents(u),incidents=all.filter(i=>(view.filter==='All'||(view.filter==='Red queue'?i.priority==='High'&&!['Resolved','Dismissed'].includes(i.status):i.status===view.filter))&&matches(i.id,i.title,i.description,student(i.studentId)?.name));return heading(u.role==='Coordinator'?'Incident & Compliance Hub (Scope 4.4)':u.role==='Student'?'Incident & Safety Claims (Scope 2.5)':'Supervisor Incident & Claims Management','Track reports, supporting evidence, and case resolutions.',u.role==='Coordinator'?'':button(u.role==='Student'?'File Incident Claim':'Create Supervisor Log','incident-new','','','plus'))+'<div class="grid-4 stat-grid-bordered incident-stat">'+stat('Active Claims',all.filter(i=>!['Resolved','Dismissed'].includes(i.status)).length,'Open cases','file')+stat('High Severity',all.filter(i=>i.priority==='High').length,'Priority attention','alert')+stat('Under Investigation',all.filter(i=>i.status==='Scheduled').length,'Mediation scheduled','search')+stat('Resolved',all.filter(i=>i.status==='Resolved').length,'Completed cases','check')+'</div><section class="incident-panel">'+tabs(['All','Pending','Scheduled','Resolved',...(u.role==='Coordinator'?['Red queue','Dismissed']:[])])+searchToolbar('Search cases, students or details')+(incidents.length?table(['Report ID','Source','Student','HTE Partner','Category','Date Reported','Severity','Status','Action'],incidents.map(i=>'<tr><td><strong>'+e(i.id)+'</strong></td><td>'+e(i.category==='Student_Claim'?'Student Claim':'Supervisor')+'</td><td>'+e(student(i.studentId)?.name)+'</td><td>'+e(student(i.studentId)?.company||'—')+'</td><td>'+e(i.title)+'</td><td>'+date(i.date)+'</td><td>'+badge(i.priority)+'</td><td>'+badge(i.status)+'</td><td>'+button('Review','incident-detail',i.id,'secondary small')+'</td></tr>')):empty('No cases in this view','Reports matching your filters will appear here.'))+'<div class="table-footer"><span>Showing '+incidents.length+' cases</span><span>Page 1</span></div></section>';}
function appraisalsPage(u){if(u.role==='Student'){const appraisal=db.appraisals.find(a=>a.studentId===u.id);return `${heading('Performance Appraisal','Your supervisor’s feedback on your progress and professional growth.')}${appraisal?`<div class="narrow-wide"><section class="card sand"><span class="eyebrow">OVERALL PERFORMANCE</span><div class="score">${appraisal.score.toFixed(1)}<span class="muted small"> / 5.0</span></div>${badge('Completed')}<p class="small mt16">Evaluated by ${e(student(appraisal.supervisorId)?.name)}<br>${date(appraisal.date)}</p>${button('Print appraisal','print','','secondary','download')}</section><section class="card"><h2>Performance breakdown</h2>${rubric.map((r,i)=>`<div class="activity-item"><div class="row between"><strong class="small">${r}</strong><span>${appraisal.ratings[i]} / 5</span></div><progress class="progress" max="5" value="${appraisal.ratings[i]}" aria-label="${r}: ${appraisal.ratings[i]} out of 5"></progress></div>`).join('')}<h3 class="mt16">Supervisor comments</h3><p>${e(appraisal.comments)}</p><p class="small muted">Typed demo signature: ${e(appraisal.signature)}</p></section></div>`:empty('Your appraisal is not available yet','Your supervisor’s submitted evaluation will appear here. Continue tracking your progress in the DTR Hub.')}`;}
  const list=visibleStudents(db,u).filter(s=>matches(s.name,s.course));return heading('Performance Appraisal','Evaluate intern performance and provide structured feedback.')+'<section class="card sand">'+searchToolbar('Search name or cohort')+table(['Intern','Department','Evaluation Period','Score','Status','Action'],list.map(s=>{const a=db.appraisals.find(a=>a.studentId===s.id);return '<tr><td>'+person(s)+'</td><td>IT Department</td><td>Final Evaluation</td><td>'+(a?a.score.toFixed(1)+' / 5':'—')+'</td><td>'+badge(a?'Completed':'Pending')+'</td><td>'+button(a?'Review':'Evaluate','evaluate',s.id,'secondary small')+'</td></tr>';}))+'</section>';}

function htePage(){const list=db.htes.filter(h=>matches(h.name,h.industry,h.location)&&(view.filter==='All'||(view.filter==='Expiring soon'?new Date(h.expiry)-Date.now()<60*86400000:h.status===view.filter)));return heading('HTE Accreditation Management','Manage host training establishments, accreditations, and MOA compliance.',button('Add New HTE','hte-edit','','','plus')+link('Job Management','jobs','secondary'))+'<div class="grid-4 stat-grid-bordered">'+stat('Total HTEs',db.htes.length,'Registered partners','building')+stat('Active',db.htes.filter(h=>h.status==='Accredited').length,'Accredited companies','check')+stat('Expiring Soon',db.htes.filter(h=>new Date(h.expiry)-Date.now()<60*86400000).length,'Within 60 days','clock')+stat('Pending Review',db.htes.filter(h=>h.status==='Pending').length,'Awaiting accreditation','file')+'</div><section class="card sand section-space">'+tabs(['All','Accredited','Pending','Expiring soon'])+searchToolbar('Search company or location')+table(['Company / HTE','Status','MOA Expiry','Industry','Location','Actions'],list.map(h=>'<tr><td><strong>'+e(h.name)+'</strong></td><td>'+badge(h.status)+'</td><td>'+date(h.expiry)+'</td><td>'+e(h.industry)+'</td><td>'+e(h.location)+'</td><td>'+button('View / Renew','hte-edit',h.id,'secondary small')+'</td></tr>'))+'</section><div class="grid-2 section-space"><section class="card sand"><h2>Compliance Metrics</h2><p>Accredited partners</p>'+progress(db.htes.filter(h=>h.status==='Accredited').length,Math.max(db.htes.length,1))+'<p>Students placed with HTEs</p>'+progress(db.users.filter(u=>u.role==='Student'&&u.company).length,Math.max(db.users.filter(u=>u.role==='Student').length,1))+'</section><section class="card sand"><h2>Recent Activity</h2>'+(db.audit.slice(0,3).map(a=>'<p>'+e(a.action)+'<small>'+date(a.date)+'</small></p>').join('')||'<p>No recent accreditation changes.</p>')+'</section></div><section class="card sand section-space"><h2>HTE Verification Workflow</h2><div class="row between wrap"><span>1. Company registration</span><span>2. Document review</span><span>3. MOA verification</span><span>4. Accreditation</span><span>5. Active partnership</span></div></section>';}
function reportsPage(){const all=db.users.filter(u=>u.role==='Student');return heading('CHED Report Generator','Generate reports for student placement, completion, HTE performance, and compliance.')+'<section class="card report-parameters"><h2>Report Parameters</h2><div class="grid-3">'+field('Date generated','reportDate','date',today(),'readonly')+field('Academic Year','reportYear','text','2025–2026','readonly')+field('Semester','reportSemester','text','Current cohort','readonly')+'</div></section><h2>Available CHED Reports</h2><section class="card report-analytics"><h2>Performance Analytics Preview</h2><div class="report-bars">'+db.htes.map(h=>{const placed=all.filter(s=>s.company===h.name);return '<div><div class="row between"><strong class="small">'+e(h.name)+'</strong><small>'+placed.length+' interns</small></div>'+progress(placed.reduce((n,s)=>n+approvedHours(db,s.id),0),Math.max(1,placed.reduce((n,s)=>n+s.requiredHours,0)))+'</div>';}).join('')+'</div></section><div class="grid-2">'+[['deployment','Student Deployment Report','Current placements, host companies, supervisors, and accreditation status.'],['completion','Completion Summary Report','Approved attendance hours and completion percentages.'],['hte','HTE Performance Report','Company accreditation, MOA expiry, and student placements.'],['compliance','Compliance Audit Report','DTR verification status, attendance justifications, and review remarks.']].map(([id,title,desc])=>'<section class="card sand"><div class="row"><span class="avatar square">'+icon('file')+'</span><h2>'+title+'</h2></div><p class="small">'+desc+'</p>'+button('Generate Report','report-preview',id,'','download')+'</section>').join('')+'</div>';}
function usersPage(){const counts=[['Total Accounts',db.users.length],['Active Users',db.users.filter(u=>u.status==='Active').length],['Students',db.users.filter(u=>u.role==='Student').length],['Faculty',db.users.filter(u=>u.role==='Coordinator').length],['Pending Activation',db.users.filter(u=>u.status==='Pending_Activation').length]];return heading('User Management & Access Governance','Pre-seed OJT candidates, provision faculty, and manage role-based access.',button('Activate Account','activation-help','','secondary')+button('Add New User','user-new','','','plus'))+tabs(['All','Registered users','Role-based access'])+(view.filter==='Role-based access'?'<div class="grid-3">'+roles.map(r=>'<section class="card sand"><h2>'+r+'</h2><ul class="permission-list">'+navigation[r].map(n=>'<li>'+icon('check')+n[1]+'</li>').join('')+'</ul></section>').join('')+'</div><p class="note mt16">Frontend route guards are a preview. Your API must enforce role and record ownership on every request.</p>':'<div class="stat-grid-five">'+counts.map(([label,n])=>stat(label,n,'','users')).join('')+'</div>'+(view.filter==='All'?'<section class="card governance-upload"><div class="row between"><h2>Pre-Seed OJT Candidates</h2>'+button('Download CSV Template','csv-template','','secondary small','download')+'</div><button class="upload-drop" data-action="import-users">'+icon('upload')+'<strong>Click to upload your student CSV</strong><span>Required: identifier, name, email, course · Up to 500 candidates</span></button></section><section class="faculty-form"><h2>Faculty / Coordinator Invitation</h2><p class="small">Provision faculty accounts with an identifier and institutional email.</p>'+button('Invite / Provision Faculty','user-new','','','plus')+'</section>':'')+'<section class="card sand section-space"><h2>Recent Registrations</h2>'+searchToolbar('Search name, identifier or role')+table(['User','Identifier','Role','Status','Actions'],db.users.filter(u=>matches(u.name,u.identifier,u.role)).map(u=>'<tr><td><strong>'+e(u.name)+'</strong><small>'+e(u.email)+'</small></td><td>'+e(u.identifier)+'</td><td>'+badge(u.role)+'</td><td>'+badge(u.status)+'</td><td>'+(u.id===currentUser().id?'Current account':button(u.status==='Active'?'Suspend':'Activate','user-status',u.id,'secondary small'))+'</td></tr>'))+'</section>');}
function notificationsPage(u){const notes=db.notifications.filter(n=>n.userId===u.id&&(view.filter==='All'||(view.filter==='Unread'?!n.read:view.filter==='Incidents'?n.type==='Incident_Alert':n.type!=='Incident_Alert')));return heading('Notifications Center','Stay updated with your OJT activities and important announcements.',button('Clear Read','clear-read','','secondary')+button('Mark All as Read','read-all','','','check'))+tabs(['All','Unread','System','Incidents'])+'<div class="notification-list">'+(notes.length?notes.map(n=>'<article class="notification-row '+(n.read?'read':'unread')+'"><div class="row between"><h3>'+(n.read?'':'● ')+e(n.title)+'</h3><small>'+date(n.date)+'</small></div><p>'+e(n.message)+'</p>'+(!n.read?button('Mark read','read',n.id,'secondary small'):'')+'</article>').join(''):empty('You’re all caught up','New updates will appear here.'))+'</div>';}
function profilePage(u){return `${heading('Profile & Settings','Keep your contact and internship details up to date.')}<div class="narrow-wide"><section class="card sand"><div class="row">${person(u)}</div><hr class="hr"><p class="small">${e(u.identifier)}</p>${badge(u.role)} ${badge(u.badge||u.status)}<p class="small muted mt16">Your role and academic identifier are managed by your coordinator.</p></section><section class="card"><h2>Personal information</h2><form id="profile-form">${field('Full name','name','text',u.name,'required maxlength="100" autocomplete="name"')}${field('Email address','email','email',u.email,'required autocomplete="email"')}${field('Phone number (optional)','phone','tel',u.phone||'','maxlength="30" autocomplete="tel"')}${textarea('About you (optional)','bio',u.bio||'','')}<p class="form-error" role="alert"></p><button class="btn" type="submit">Save profile</button></form></section></div><section class="card section-space"><h2>Demonstration settings</h2><p class="small muted">All data in this preview is stored on this device. Do not enter real student information, passwords, or sensitive incident evidence.</p><div class="row wrap">${button('Switch portal','switch-role','','secondary','users')}${button('Reset sample data','reset-demo','','secondary')}${button('Sign out','logout','','secondary','logout')}</div></section>`;}
function documentsPage(u){const docs=db.documents.filter(d=>d.studentId===u.id);return heading('Document Management Portal','Upload and manage your OJT requirements and supporting documents.')+'<button class="upload-drop" data-action="document-upload">'+icon('upload')+'<strong>Drop files here, or click to upload</strong><span>PDF, JPG, PNG · Up to 5 MB per file · MOA, Medical, Waiver, Clearance</span></button><section class="document-list"><h2>Submitted Documents</h2>'+(docs.length?docs.map(d=>'<article class="document-item"><span class="document-icon">'+icon('file')+'</span><div class="document-copy"><strong>'+e(d.name)+'</strong><p>'+e(d.category)+' · '+date(d.date)+' · '+Math.round(d.size/1024)+' KB</p></div>'+badge('Pending')+button('Download','file-download',d.id,'secondary small','download')+button('Remove','document-remove',d.id,'secondary small')+'</article>').join(''):empty('No documents submitted','Upload your requirements using the area above.'))+'</section>';}
function safeMeetingURL(value){const url=new URL(value);if(url.protocol!=='https:'||!['meet.google.com','teams.microsoft.com','teams.live.com','zoom.us','www.zoom.us'].some(h=>url.hostname===h||url.hostname.endsWith('.'+h)))throw new Error('Use an HTTPS Google Meet, Microsoft Teams, or Zoom link.');return url.href;}
function openJob(id){const u=currentUser(),j=job(id);if(!j)return;const applied=db.applications.some(a=>a.studentId===u.id&&a.jobId===id&&a.status!=='Rejected');showModal(e(j.title),`<div class="row between"><strong>${e(j.company)}</strong>${badge(j.status)}</div><p class="muted mt16">${e(j.location)} · ${e(j.mode)} · ${j.slots} available slots</p><h3>About this opportunity</h3><p>${e(j.description)}</p><h3>Skills you’ll use</h3><p>${e(j.skills)}</p><h3>Host training establishment specifications</h3><p>${e(j.specs)}</p><h3>Eligible programs</h3><p>${e(j.courses.join(' · '))}</p>${u.role==='Student'?`<div class="note">${applied?'You already applied to this position.':'Your current profile will be included with your application.'}</div>${applied?'':`<div class="field mt16"><label class="row"><input type="checkbox" name="consent" required> I confirm my profile details are ready for review.</label></div>`}`:''}${u.role!=='Student'?button('Edit position','job-edit',id,'secondary'):''}`,u.role==='Student'&&!applied&&j.status==='Active'&&j.slots>0?(data)=>{const a=applyToJob(db,u,id);if(j.supervisorId)notify(j.supervisorId,'Application_Status','New internship application',u.name+' applied for '+j.title+'.');audit('Submitted application for '+j.title);save();toast('Application submitted in the demo.');}:null,'Submit application');}
function editJob(id){const u=currentUser();if(!['Coordinator','Supervisor'].includes(u.role))throw new Error('This role cannot manage positions.');const j=job(id);if(j&&u.role==='Supervisor'&&j.supervisorId!==u.id)throw new Error('This position is outside your scope.');showModal(j?'Edit position':'Post a new position',field('Position title','title','text',j?.title||'','required maxlength="120"')+field('Company','company','text',j?.company||u.company||'','required maxlength="120" '+(u.role==='Supervisor'?'readonly':''))+`<div class="grid-2">${field('Location','location','text',j?.location||'','required maxlength="100"')}${select('Work arrangement','mode',['On-site','Hybrid','Remote'],j?.mode||'On-site')}</div><div class="grid-2">${field('Available slots','slots','number',j?.slots??1,'required min="0" max="1000"')}${select('Status','status',['Draft','Active','Closed'],j?.status||'Draft')}</div>`+select('Eligible program','course',['All IT programs','BS Computer Science','BS Information Technology','BS Computer Engineering'],j?.courses?.length===1?j.courses[0]:'All IT programs')+textarea('Position description','description',j?.description||'')+field('Skills','skills','text',j?.skills||'','required maxlength="200"')+textarea('HTE specifications & requirements','specs',j?.specs||'')+(u.role==='Coordinator'?select('Assigned supervisor','supervisorId',[['','Unassigned'],...db.users.filter(s=>s.role==='Supervisor').map(s=>[s.id,s.name])],j?.supervisorId||''):''),data=>{const values={...data,slots:Number(data.slots),courses:data.course==='All IT programs'?['BS Computer Science','BS Information Technology','BS Computer Engineering']:[data.course],supervisorId:u.role==='Supervisor'?u.id:data.supervisorId||null};delete values.course;if(j)Object.assign(j,values);else db.jobs.unshift({id:crypto.randomUUID(),...values});audit((j?'Updated':'Created')+' position '+values.title);save();toast('Position saved.');},'Save position');}
function applicationDetail(id){const u=currentUser(),a=visibleApplications(db,u).find(a=>a.id===id);if(!a)throw new Error('Application unavailable.');const j=job(a.jobId),s=student(a.studentId);showModal('Application details',`<h3>${e(j.title)}</h3><p>${e(j.company)} · ${e(s.name)}</p>${badge(a.status)}<div class="timeline"><div class="timeline-item"><strong>Application submitted</strong><p>${date(a.date)}</p></div><div class="timeline-item"><strong>Supervisor review</strong><p>${a.status==='Pending'?'Awaiting review':e(a.status.replaceAll('_',' '))}</p></div><div class="timeline-item"><strong>Placement & endorsement</strong><p>${a.status==='Accepted'?e(a.note||'Application accepted. Coordinator endorsement is next.'):'Follows an accepted application.'}</p></div></div>${u.role==='Supervisor'?select('Review decision','status',['Pending','Under_Review','Accepted','Rejected'],a.status)+textarea('Review note','note',a.note||''):''}`,u.role==='Supervisor'?data=>{if(data.status==='Accepted'&&a.status!=='Accepted'){if(j.slots<1)throw new Error('No slots remain in this position.');if(db.applications.some(other=>other.studentId===s.id&&other.id!==a.id&&other.status==='Accepted'))throw new Error('This student already has an accepted placement.');j.slots--;s.company=j.company;s.supervisorId=u.id;s.badge='Enrolled';}if(a.status==='Accepted'&&data.status!=='Accepted')throw new Error('An accepted placement must be reassigned by the coordinator.');Object.assign(a,data);notify(s.id,'Application_Status','Application status updated',j.title+': '+data.status.replaceAll('_',' '));audit('Reviewed application for '+s.name);save();toast('Application updated.');}:null,'Save review');}
async function clockAction(){const u=currentUser();if(u.role!=='Student')throw new Error('Only students can clock in.');if(!u.supervisorId)throw new Error('You need an assigned supervisor before logging attendance.');if(db.shift&&db.shift.studentId!==u.id)throw new Error('Another demo student has an active shift. Finish that shift first.');if(!db.shift){const pending=$('[data-action="clock"]');pending.disabled=true;pending.textContent='Requesting location…';let gps=null;try{const pos=await new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(new Error());navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:true,timeout:8000,maximumAge:0});});gps={lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy};}catch{}if(currentUser()?.id!==u.id)return;db.shift={studentId:u.id,clockIn:new Date().toISOString(),gps};save();render();toast(gps?'Clocked in. Location captured, pending server verification.':'Clocked in without location. Add a justification when submitting.');return;}
  const shift=db.shift;showModal('Complete your daily time record',`<p>Shift started ${date(shift.clockIn)} at ${time(shift.clockIn)}.</p>${field('Unpaid break (minutes)','breakMinutes','number',0,'required min="0" max="720"')}${textarea('Task summary & learning reflection','task',db.draft)}${textarea('Location or attendance justification'+(shift.gps?' (optional)':''),'justification','',shift.gps?'':'required minlength="10"')}<p class="note">Location capture alone does not verify attendance. Your supervisor will review the entry and supporting context.</p>`,data=>{const end=new Date().toISOString(),hours=hoursBetween(shift.clockIn,end,Number(data.breakMinutes));if(hours<=0)throw new Error('The shift is too short to record. Wait at least 20 seconds before submitting.');db.logs.push({id:crypto.randomUUID(),studentId:u.id,supervisorId:u.supervisorId,date:today(),clockIn:shift.clockIn,clockOut:end,breakMinutes:Number(data.breakMinutes),hours,task:data.task,justification:data.justification,gps:shift.gps,status:'Pending',remarks:'',signature:''});db.shift=null;db.draft='';notify(u.supervisorId,'DTR_Event','Daily time record submitted',u.name+' submitted '+hours.toFixed(2)+' hours for review.');audit('Submitted a daily time record');save();toast('Shift completed and submitted for review.');},'Clock out & submit');}
function logDetail(id){const u=currentUser(),l=visibleLogs(db,u).find(l=>l.id===id);if(!l)throw new Error('Attendance entry unavailable.');const review=u.role==='Supervisor'&&['Pending','Flagged'].includes(l.status),justify=u.role==='Student'&&['Flagged','Rejected'].includes(l.status);showModal('Daily time record',`<div class="row between"><strong>${e(student(l.studentId)?.name)}</strong>${badge(l.status)}</div><p class="muted mt16">${date(l.date)} · ${time(l.clockIn)} – ${time(l.clockOut)} · ${l.hours} hours</p><h3>Task summary</h3><p>${e(l.task)}</p><p class="small"><strong>Location:</strong> ${l.gps?'Captured on device; not server-verified':'Not captured'}</p>${l.justification?`<h3>Justification</h3><p>${e(l.justification)}</p>`:''}${l.remarks?`<h3>Supervisor remarks</h3><p>${e(l.remarks)}</p>`:''}${l.signature?`<p class="small muted">Demo typed signature: ${e(l.signature)}</p>`:''}${review?select('Review decision','status',['Approved','Flagged','Rejected'])+textarea('Review remarks','remarks',l.remarks||'')+field('Typed signature (demo)','signature','text',u.name,'required maxlength="100"')+'<label class="row small"><input type="checkbox" required> I reviewed this attendance record.</label>':justify?textarea('Justification for re-review','justification',l.justification||'','required minlength="10"'):''}`,review?data=>{reviewLog(db,u,id,data.status,data.remarks,data.signature);notify(l.studentId,'DTR_Event','DTR entry '+data.status.toLowerCase(),date(l.date)+': '+data.remarks);audit('Marked '+student(l.studentId).name+' DTR '+data.status);save();toast('DTR review saved.');}:justify?data=>{l.justification=data.justification;l.status='Pending';notify(l.supervisorId,'DTR_Event','Justification submitted',u.name+' resubmitted an attendance entry for review.');audit('Submitted attendance justification');save();toast('Justification sent for re-review.');}:null,'Submit review');}
function studentDetail(id){const u=currentUser(),s=visibleStudents(db,u).find(s=>s.id===id);if(!s)throw new Error('Student is outside your assigned scope.');showModal(e(s.name),`${person(s)}<hr class="hr"><div class="grid-2"><div><span class="small muted">SR code</span><p>${e(s.identifier)}</p><span class="small muted">Host company</span><p>${e(s.company||'Unplaced')}</p></div><div><span class="small muted">Approved hours</span><p>${approvedHours(db,s.id)} / ${s.requiredHours} hours</p><span class="small muted">Accreditation</span><p>${badge(s.badge)}</p></div></div>${progress(approvedHours(db,s.id),s.requiredHours)}<h3 class="mt16">Recent attendance</h3>${dtrTable(db.logs.filter(l=>l.studentId===s.id).slice(-3),{role:'Student'})}${u.role==='Coordinator'?`<hr class="hr">${select('Host company','company',[['','Unplaced'],...db.htes.filter(h=>h.status==='Accredited').map(h=>h.name)],s.company)}${select('Assigned supervisor','supervisorId',[['','Unassigned'],...db.users.filter(v=>v.role==='Supervisor'&&v.status==='Active').map(v=>[v.id,v.name])],s.supervisorId||'')}${select('Accreditation status','badge',['Pre_Seeded','Eligible','Enrolled','Cleared'],s.badge)}${field('Required OJT hours','requiredHours','number',s.requiredHours,'required min="1" max="2000"')}<p class="small muted">Clearance requires completed hours, an appraisal, and no unresolved incidents.</p>${button('Download endorsement','endorsement',s.id,'secondary small','download')}`:''}`,u.role==='Coordinator'?data=>{const supervisor=student(data.supervisorId);if(data.company&&(!supervisor||supervisor.company!==data.company))throw new Error('Select a supervisor from the chosen host company.');if(!data.company&&data.supervisorId)throw new Error('Assign a host company before a supervisor.');if(data.badge==='Cleared'&&(approvedHours(db,id)<Number(data.requiredHours)||!db.appraisals.some(a=>a.studentId===id)||db.incidents.some(i=>i.studentId===id&&!['Resolved','Dismissed'].includes(i.status))))throw new Error('This student has incomplete clearance requirements.');Object.assign(s,{...data,supervisorId:data.supervisorId||null,requiredHours:Number(data.requiredHours)});notify(s.id,'System','Placement profile updated','Your coordinator updated your placement or accreditation details.');audit('Updated placement for '+s.name);save();toast('Student placement updated.');}:null,'Save placement');}
function incidentNew(){const u=currentUser(),students=visibleStudents(db,u);showModal(u.role==='Student'?'File an incident claim':'Create disciplinary log',`<p class="note">Document the situation clearly. This demo does not send emergency alerts or contact school staff.</p>${u.role==='Supervisor'?select('Student involved','studentId',students.map(s=>[s.id,s.name])):''}${field('Short title','title','text','','required maxlength="120"')}${select('Priority','priority',['Low','Medium','High'],'Medium')}${textarea('Description','description','','required minlength="20"')}${select('Related DTR (optional)','logId',[['','No linked entry'],...visibleLogs(db,u).map(l=>[l.id,student(l.studentId).name+' · '+date(l.date)])])}${field('Evidence (optional, PDF / PNG / JPEG, up to 5 MB)','evidence','file','','accept="application/pdf,image/png,image/jpeg"')}`,async(data,form)=>{const sid=u.role==='Student'?u.id:data.studentId;if(u.role==='Supervisor'&&!students.some(s=>s.id===sid))throw new Error('Choose an assigned intern.');if(data.logId&&!db.logs.some(l=>l.id===data.logId&&l.studentId===sid))throw new Error('The linked DTR must belong to the selected student.');let evidence=null;const file=form.elements.evidence.files[0];if(file){validateUpload(file);evidence={id:crypto.randomUUID(),name:file.name};await putFile(evidence.id,file);}const incident={id:'IR-'+crypto.randomUUID().slice(0,8).toUpperCase(),studentId:sid,supervisorId:u.role==='Supervisor'?u.id:u.supervisorId,category:u.role==='Student'?'Student_Claim':'Disciplinary_Violation',title:data.title,description:data.description,priority:data.priority,status:'Pending',date:today(),logId:data.logId||null,evidence,notes:[],meeting:null};db.incidents.unshift(incident);db.users.filter(v=>v.role==='Coordinator').forEach(v=>notify(v.id,'Incident_Alert','New incident report',incident.id+': '+incident.title));audit('Filed incident '+incident.id);save();toast('Incident saved for coordinator review.');},'Submit report');}
function incidentDetail(id){const u=currentUser(),i=visibleIncidents(u).find(i=>i.id===id);if(!i)throw new Error('Case unavailable.');showModal('Case '+e(i.id),`<div class="row between"><h3 class="mb0">${e(i.title)}</h3>${badge(i.priority)}</div><p class="small muted mt16">${e(student(i.studentId)?.name)} · ${date(i.date)} · ${e(i.category.replaceAll('_',' '))}</p>${badge(i.status)}<p class="mt16">${e(i.description)}</p>${i.logId?button('View linked DTR','log-detail',i.logId,'secondary small'):''}${i.evidence?button('Download evidence: '+e(i.evidence.name),'file-download',i.evidence.id,'secondary small','download'):''}${i.meeting?`<section class="note mt16"><strong>Mediation scheduled</strong><p class="mb0">${date(i.meeting.time)} · ${time(i.meeting.time)} · ${e(i.meeting.platform)}</p><a href="${e(safeMeetingURL(i.meeting.url))}" target="_blank" rel="noopener noreferrer" class="text-btn">Open meeting →</a></section>`:''}<h3 class="mt16">Case notes</h3>${i.notes.map(n=>`<div class="activity-item"><p>${e(n.text)}</p><small>${e(n.author)} · ${date(n.date)}</small></div>`).join('')||'<p class="small muted">No case notes yet.</p>'}${u.role==='Coordinator'?`<hr class="hr">${select('Case status','status',['Pending','Scheduled','Resolved','Dismissed'],i.status)}${textarea('Investigation / resolution note','note','','required minlength="10"')}<details><summary class="small">Schedule a mediation meeting (optional)</summary><div class="mt16">${select('Meeting platform','platform',['Google Meet','MS Teams','Zoom'],i.meeting?.platform||'Google Meet')}${field('Meeting link','url','url',i.meeting?.url||'')}${field('Meeting date & time','meetingTime','datetime-local',i.meeting?.localTime||'')}</div></details>`:''}`,u.role==='Coordinator'?data=>{let meeting=i.meeting;if(data.url||data.meetingTime){if(!data.url||!data.meetingTime)throw new Error('Provide both the meeting link and time.');const url=safeMeetingURL(data.url);if(new Date(data.meetingTime)<=new Date())throw new Error('Schedule a meeting in the future.');meeting={platform:data.platform,url,time:new Date(data.meetingTime).toISOString(),localTime:data.meetingTime};}if(data.status==='Scheduled'&&!meeting)throw new Error('Add a meeting link and time before marking this case scheduled.');i.meeting=meeting;i.status=data.status;i.notes.push({text:data.note,author:u.name,date:new Date().toISOString()});notify(i.studentId,'Incident_Alert','Incident '+i.id+' updated',data.status+': '+data.note);if(i.supervisorId)notify(i.supervisorId,'Incident_Alert','Incident '+i.id+' updated',data.status+': '+data.note);audit('Updated incident '+i.id+' to '+i.status);save();toast('Case updated.');}:null,'Update case');}
function evaluate(id){const u=currentUser(),s=visibleStudents(db,u).find(s=>s.id===id);if(u.role!=='Supervisor'||!s)throw new Error('Student outside your evaluation scope.');const a=db.appraisals.find(a=>a.studentId===id);const body=`${person(s)}<hr class="hr"><p class="small muted">1 — Needs improvement · 3 — Meets expectations · 5 — Excellent</p>${rubric.map((r,i)=>`<fieldset class="rubric-row"><legend><strong>${i+1}. ${r}</strong></legend><div class="rating">${[1,2,3,4,5].map(n=>`<label><input type="radio" name="rating${i}" value="${n}" required ${a?.ratings[i]===n?'checked':''} ${a?'disabled':''}>${n}</label>`).join('')}</div></fieldset>`).join('')}${a?`<h3 class="mt16">Overall score: ${a.score.toFixed(1)} / 5</h3><p>${e(a.comments)}</p><p class="small">Signature: ${e(a.signature)}</p>`:textarea('Supervisor comments & observations','comments','','required minlength="20"')+field('Typed signature (demo)','signature','text',u.name,'required maxlength="100"')+'<label class="row small"><input type="checkbox" required> I confirm this evaluation reflects my review of the student.</label>'}`;showModal(a?'Submitted appraisal':'Performance appraisal rubric',body,a?null:data=>{const application=db.applications.find(a=>a.studentId===id&&a.status==='Accepted');if(!application)throw new Error('An accepted application is required before evaluation.');const ratings=rubric.map((r,i)=>Number(data['rating'+i]));if(ratings.some(n=>!Number.isInteger(n)||n<1||n>5))throw new Error('Complete every rubric criterion.');db.appraisals.push({id:crypto.randomUUID(),applicationId:application.id,studentId:id,supervisorId:u.id,ratings,score:ratings.reduce((a,b)=>a+b)/ratings.length,comments:data.comments,signature:data.signature,date:new Date().toISOString()});notify(id,'System','Your performance appraisal is ready','View your supervisor’s rubric scores and feedback.');audit('Submitted appraisal for '+s.name);save();toast('Evaluation submitted. The student can now view it.');},'Submit evaluation');}
function editHTE(id){const h=db.htes.find(h=>h.id===id);showModal(h?'Host training establishment':'Add new HTE',field('Company name','name','text',h?.name||'','required maxlength="120"')+field('Industry','industry','text',h?.industry||'','required maxlength="100"')+field('Location','location','text',h?.location||'','required maxlength="100"')+field('Contact email','contact','email',h?.contact||'','required')+field('MOA expiry','expiry','date',h?.expiry||'','required')+select('Accreditation status','status',['Pending','Accredited','Expired'],h?.status||'Pending'),data=>{if(data.status==='Accredited'&&new Date(data.expiry+'T23:59:59')<new Date())throw new Error('An accredited HTE must have a valid MOA expiry date.');if(db.htes.some(other=>other.id!==id&&other.name.toLowerCase()===data.name.toLowerCase()))throw new Error('This HTE already exists.');if(h){const oldName=h.name;Object.assign(h,data);db.jobs.filter(j=>j.company===oldName).forEach(j=>j.company=data.name);db.users.filter(u=>u.company===oldName).forEach(u=>u.company=data.name);}else db.htes.push({id:crypto.randomUUID(),...data});audit('Updated HTE accreditation: '+data.name);save();toast('HTE details saved.');},'Save HTE');}
function userNew(){showModal('Provision a user',select('Role','role',roles)+field('Full name','name','text','','required maxlength="100"')+field('SR code / faculty ID / corporate email','identifier','text','','required maxlength="100"')+field('Email address','email','email','','required')+select('Course (students)','course',['BS Computer Science','BS Information Technology','BS Computer Engineering'])+field('Company (supervisors)','company','text','','maxlength="120"')+'<p class="note">The demo creates a pending account. Production provisioning must send a server-generated activation link.</p>',data=>{if(db.users.some(u=>u.identifier.toLowerCase()===data.identifier.toLowerCase()||u.email.toLowerCase()===data.email.toLowerCase()))throw new Error('The identifier or email is already registered.');if(data.role==='Supervisor'&&!data.company.trim())throw new Error('A supervisor needs a company.');db.users.push({id:crypto.randomUUID(),...data,status:'Pending_Activation',badge:'Pre_Seeded',baseHours:0,requiredHours:db.program.requiredHours,supervisorId:null});audit('Provisioned '+data.role+' account for '+data.name);save();toast('Pending demo account created.');},'Create pending account');}
function importUsers(){showModal('Import OJT candidates',`<p>Required headers: <strong>identifier,name,email,course</strong>. Up to 500 students, maximum 1 MB. Duplicate identifiers or emails will stop the import.</p>${field('CSV file','csv','file','','required accept=".csv,text/csv"')}`,async(data,form)=>{const file=form.elements.csv.files[0];if(!file||file.size>1024*1024)throw new Error('Choose a CSV file smaller than 1 MB.');const rows=parseCSV(await file.text()),header=rows.shift()?.map(v=>v.toLowerCase());const required=['identifier','name','email','course'];if(!header||required.some(k=>!header.includes(k)))throw new Error('The CSV is missing required headers.');if(rows.length<1||rows.length>500)throw new Error('Import between 1 and 500 students.');const ids=new Set(db.users.map(u=>u.identifier.toLowerCase())),emails=new Set(db.users.map(u=>u.email.toLowerCase()));const batch=rows.map((r,index)=>{const o=Object.fromEntries(required.map(k=>[k,r[header.indexOf(k)]||'']));if(Object.values(o).some(v=>!v||v.length>150)||!/^\S+@\S+\.\S+$/.test(o.email))throw new Error('Invalid or missing values on row '+(index+2));if(ids.has(o.identifier.toLowerCase())||emails.has(o.email.toLowerCase()))throw new Error('Duplicate identifier or email on row '+(index+2));ids.add(o.identifier.toLowerCase());emails.add(o.email.toLowerCase());return {id:crypto.randomUUID(),...o,role:'Student',status:'Pending_Activation',badge:'Pre_Seeded',baseHours:0,requiredHours:db.program.requiredHours,company:'',supervisorId:null};});db.users.push(...batch);audit('Imported '+batch.length+' OJT candidates');save();toast(batch.length+' pending candidates imported.');},'Validate & import');}
function announcement(){const u=currentUser();showModal('Post a demo announcement',field('Title','title','text','','required maxlength="120"')+textarea('Announcement','message','','required minlength="10"')+'<p class="note">This creates local demo notifications. No emails or external messages are sent.</p>',data=>{const recipients=u.role==='Coordinator'?db.users.filter(v=>v.id!==u.id):visibleStudents(db,u);recipients.forEach(v=>notify(v.id,'System',data.title,data.message));audit('Posted announcement: '+data.title);save();toast('Announcement saved for '+recipients.length+' demo recipients.');},'Post announcement');}

function openFiles(){return new Promise((resolve,reject)=>{if(filesDB)return resolve(filesDB);const request=indexedDB.open('menteelog-demo-files',1);request.onupgradeneeded=()=>request.result.createObjectStore('files');request.onsuccess=()=>{filesDB=request.result;resolve(filesDB);};request.onerror=()=>reject(new Error('Browser file storage is unavailable.'));});}
async function fileOp(mode,key,value){const database=await openFiles();return new Promise((resolve,reject)=>{const tx=database.transaction('files',mode==='get'?'readonly':'readwrite'),store=tx.objectStore('files');const req=mode==='get'?store.get(key):mode==='put'?store.put(value,key):mode==='clear'?store.clear():store.delete(key);tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(new Error('File storage failed. Your browser storage may be full.'));tx.onabort=()=>reject(new Error('File storage operation was interrupted.'));});}
const putFile=(id,file)=>fileOp('put',id,file);
function documentUpload(){const u=currentUser();showModal('Upload a document',select('Document category','category',['Endorsement letter','Training agreement','Accomplishment report','Certificate','Other'])+field('Choose a file','file','file','','required accept="application/pdf,image/png,image/jpeg"')+'<p class="small muted">PDF, PNG, or JPEG · Up to 5 MB. Stored only in this browser.</p>',async(data,form)=>{const file=form.elements.file.files[0];validateUpload(file);const id=crypto.randomUUID();await putFile(id,file);db.documents.unshift({id,studentId:u.id,name:file.name,size:file.size,type:file.type,category:data.category,date:today()});audit('Uploaded a demo document');save();toast('Document saved locally.');},'Upload document');}
function exportReport(type){let rows;const students=db.users.filter(s=>s.role==='Student');switch(type){case 'completion':rows=[['Student','SR code','Approved hours','Required hours','Completion percent'],...students.map(s=>[s.name,s.identifier,approvedHours(db,s.id),s.requiredHours,Math.round(approvedHours(db,s.id)/s.requiredHours*100)])];break;case 'compliance':rows=[['Student','Date','Hours','Status','Location captured','Justification','Reviewer remarks'],...db.logs.map(l=>[student(l.studentId)?.name,l.date,l.hours,l.status,l.gps?'Yes (unverified)':'No',l.justification||'',l.remarks])];break;case 'hte':rows=[['Company','Industry','Accreditation','MOA expiry','Placed students'],...db.htes.map(h=>[h.name,h.industry,h.status,h.expiry,students.filter(s=>s.company===h.name).length])];break;case 'incidents':rows=[['Case','Student','Category','Priority','Status','Reported'],...db.incidents.map(i=>[i.id,student(i.studentId)?.name,i.category,i.priority,i.status,i.date])];break;default:rows=[['Student','SR code','Course','Host company','Supervisor','Accreditation','Approved hours','Required hours'],...students.map(s=>[s.name,s.identifier,s.course,s.company,student(s.supervisorId)?.name||'',s.badge,approvedHours(db,s.id),s.requiredHours])];}download('MenteeLog-'+type+'-DEMO.csv',csvText(rows));toast('Sample data report downloaded.');}
const actionRoles={ 'job-edit':['Supervisor','Coordinator'],'student-detail':['Supervisor','Coordinator'],'evaluate':['Supervisor'],'hte-edit':['Coordinator'],'user-new':['Coordinator'],'user-status':['Coordinator'],'import-users':['Coordinator'],'csv-template':['Coordinator'],'announcement':['Supervisor','Coordinator'],'document-upload':['Student'],'document-remove':['Student'],'clock':['Student'],'incident-new':['Student','Supervisor'],'report':['Coordinator'],'export-students':['Supervisor','Coordinator'],'endorsement':['Coordinator']};
async function action(name,id,el){
  const publicActions=['demo','auth-role','forgot','toggle-password','close','watch-demo','privacy','team-connect'];
  const u=currentUser();
  if(!publicActions.includes(name)&&!u){logout();location.hash='/login';throw new Error('Your demo session expired. Sign in again.');}
  if(actionRoles[name]&&!actionRoles[name].includes(u?.role))throw new Error('This action is unavailable for your role.');
  switch(name){
    case 'watch-demo':showModal('Explore MenteeLog','<p>Follow the OJT journey through three connected portals.</p><ol><li>Student: find a placement, submit attendance, and view feedback.</li><li>Supervisor: review applications, attendance, and appraisals.</li><li>Coordinator: manage placements, compliance, and user governance.</li></ol><p>This is an interactive frontend preview. No video was supplied.</p><a class="btn full" href="#/login">Open Authentication Hub</a>');return;
    case 'privacy':showModal('Privacy & data protection','<p>This frontend preview uses sample records stored in your browser. Your team must connect the authentication and authorized API endpoints before handling real student information.</p>');return;
    case 'team-connect':showModal('Team contact','<p>Contact details for '+e(id)+' have not been provided.</p>');return;
    case 'close':modal.close();return;
    case 'demo':{const role=roles.includes(id)?id:'Student',user=db.users.find(u=>u.role===role&&u.status==='Active');if(!user)throw new Error('This demo role has no active account. Reset demo data from an active coordinator account.');storeSession(user);modal.close();view={search:'',filter:'All',course:'All',mode:'All'};location.hash='/'+role.toLowerCase()+'/dashboard';render();return;}
    case 'auth-role':authRole=id;render();return;
    case 'toggle-password':{const input=$('#password');input.type=input.type==='password'?'text':'password';el.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password');return;}
    case 'forgot':showModal('Forgot your password?',`<p>Enter the email associated with your account.</p>${field('Email address','email','email','','required autocomplete="email"')}<p class="note">Demo preview: no reset email will be sent. Production password recovery requires the authentication API.</p>`,()=>{toast('Demo preview complete. No email was sent.');},'Preview reset request');return;
    case 'logout':logout();return;
    case 'switch-role':showModal('Explore another portal',`<p>Use the sample accounts to see how the three roles work together.</p><div class="stack">${roles.map(r=>button('Open '+r+' demo','demo',r,'secondary full')).join('')}</div>`);return;
    case 'menu':$('#sidebar').classList.toggle('open');document.querySelectorAll('[data-action="menu"]').forEach(b=>b.setAttribute('aria-expanded',$('#sidebar').classList.contains('open')));return;
    case 'filter':view.filter=id;render();return;
    case 'notifications':{const old=$('#notice-drawer');if(old){old.remove();return;}const drawer=document.createElement('section');drawer.id='notice-drawer';drawer.className='notice-drawer';drawer.setAttribute('aria-label','Recent notifications');drawer.innerHTML=notificationsMini(u);app.append(drawer);return;}
    case 'read':{const n=db.notifications.find(n=>n.id===id&&n.userId===u.id);if(n)n.read=true;break;}
    case 'read-all':db.notifications.filter(n=>n.userId===u.id).forEach(n=>n.read=true);toast('All notifications marked as read.');break;
    case 'clear-read':db.notifications=db.notifications.filter(n=>n.userId!==u.id||!n.read);toast('Read notifications cleared.');break;
    case 'job-detail':openJob(id);return;
    case 'job-edit':editJob(id);return;
    case 'application-detail':applicationDetail(id);return;
    case 'clock':await clockAction();return;
    case 'log-detail':logDetail(id);return;
    case 'student-detail':studentDetail(id);return;
    case 'incident-new':incidentNew();return;
    case 'incident-detail':incidentDetail(id);return;
    case 'evaluate':evaluate(id);return;
    case 'hte-edit':editHTE(id);return;
    case 'user-new':userNew();return;
    case 'import-users':importUsers();return;
    case 'user-status':{const target=student(id);if(!target||target.id===u.id)throw new Error('You cannot change your own account status.');showModal(target.status==='Active'?'Suspend demo account?':'Activate demo account?',`<p>${e(target.name)} (${e(target.role)}) will be ${target.status==='Active'?'unable':'able'} to use this demo account. This changes only local demonstration data.</p>`,()=>{target.status=target.status==='Active'?'Suspended':'Active';audit('Changed account status for '+target.name);save();toast('Demo account updated.');},'Confirm change');return;}
    case 'csv-template':download('menteelog-candidates-template.csv','identifier,name,email,course\r\n2026-01001,Sample Student,student@example.edu,BS Information Technology\r\n');return;
    case 'announcement':announcement();return;
    
    
    case 'document-upload':documentUpload();return;
    case 'document-remove':{const doc=db.documents.find(d=>d.id===id&&d.studentId===u.id);if(!doc)throw new Error('Document unavailable.');showModal('Remove document?',`<p>Remove <strong>${e(doc.name)}</strong> from this browser’s demo storage?</p>`,async()=>{await fileOp('delete',id);db.documents=db.documents.filter(d=>d.id!==id);save();toast('Document removed.');},'Remove document');return;}
    case 'file-download':{const doc=db.documents.find(d=>d.id===id&&d.studentId===u.id)||visibleIncidents(u).find(i=>i.evidence?.id===id)?.evidence;if(!doc)throw new Error('File is outside your access scope.');const file=await fileOp('get',id);if(!file)throw new Error('This file is no longer in browser storage. Please upload it again.');download(doc.name,file);return;}
    case 'report-preview':{if(u.role!=='Coordinator')throw new Error('Coordinator role required.');showModal('Report Preview','<p>This report uses the current sample records. Download the CSV to review it in a spreadsheet, or print this portal page.</p><div class="row">'+button('Download CSV','report',id,'','download')+button('Print','print','','secondary')+'</div>');return;}
    case 'activation-help':showModal('Account activation','<p>Find an account in Registered users and select Activate. This affects only the local preview; email links and token verification require the authentication API.</p>');return;
    case 'report':exportReport(id);return;
    case 'export-students':{const list=visibleStudents(db,u);download('MenteeLog-roster-DEMO.csv',csvText([['Name','SR code','Course','Company','Approved hours','Required hours','Badge'],...list.map(s=>[s.name,s.identifier,s.course,s.company,approvedHours(db,s.id),s.requiredHours,s.badge])]));return;}
    case 'export-dtr':download('MenteeLog-DTR-DEMO.csv',csvText([['Student','Date','Clock in','Clock out','Break minutes','Hours','Status','Task','Remarks'],...visibleLogs(db,u).map(l=>[student(l.studentId)?.name,l.date,l.clockIn,l.clockOut,l.breakMinutes,l.hours,l.status,l.task,l.remarks])]));return;
    case 'endorsement':{const s=student(id);if(!s||!s.company)throw new Error('Assign a company before generating an endorsement.');download('MenteeLog-endorsement-DEMO.txt',`MENTEELOG — DRAFT ENDORSEMENT (DEMONSTRATION ONLY)\n\nDate: ${date(today())}\nStudent: ${s.name}\nSR Code: ${s.identifier}\nProgram: ${s.course}\nHost Training Establishment: ${s.company}\nSupervisor: ${student(s.supervisorId)?.name||'Not assigned'}\nRequired Hours: ${s.requiredHours}\n\nThis draft must be reviewed and signed by the authorized faculty coordinator before official use.\n\nPrepared by: ${u.name}\n`,'text/plain;charset=utf-8');return;}
    case 'print':window.print();return;
    case 'reset-demo':showModal('Reset the demonstration?',`<p>This removes demo records and uploaded files from this browser and restores the sample cohort. Your source files and Figma references are not affected.</p>`,async()=>{await fileOp('clear');db=ensureCreatorAccounts(seedData());save();logout();toast('Sample data restored.');},'Reset demo');return;
    default:return;
  }save();render();
}
document.addEventListener('click',event=>{if(event.target.closest('.skip-link')){event.preventDefault();const main=$('#main');main?.setAttribute('tabindex','-1');main?.focus();return;}const roleLink=event.target.closest('[data-role]');if(roleLink)authRole=roleLink.dataset.role;const target=event.target.closest('[data-action]');if(!target)return;event.preventDefault();action(target.dataset.action,target.dataset.id,target).catch(error=>toast(error.message));});
document.addEventListener('input',event=>{if(event.target.id==='draft'){db.draft=event.target.value;save();}});
document.addEventListener('change',event=>{if(event.target.id==='partner'){view.partner=event.target.value;render();}if(event.target.closest('#search-form')&&event.target.tagName==='SELECT')event.target.form.requestSubmit();});
document.addEventListener('keydown',event=>{if(event.key==='Escape')$('#sidebar')?.classList.remove('open');if(event.target.id==='global-search'&&event.key==='Enter'){event.preventDefault();const q=event.target.value.toLowerCase().trim();const match=navigation[currentUser().role].find(n=>n[1].toLowerCase().includes(q));if(q&&match)location.hash='/'+currentUser().role.toLowerCase()+'/'+match[0];else toast('No matching page found. Try “DTR”, “placement”, or “reports”.');}});
document.addEventListener('submit',async event=>{
  const form=event.target;if(!form.id)return;event.preventDefault();const values=Object.fromEntries(new FormData(form));const errorBox=form.querySelector('.form-error');if(errorBox)errorBox.textContent='';const submit=form.querySelector('[type="submit"]');if(submit)submit.disabled=true;
  try{
    if(form.id==='login-form'){const user=db.users.find(u=>u.role===authRole&&u.identifier.toLowerCase()===values.identifier.trim().toLowerCase()&&u.status==='Active');if(!user||values.password!=='Demo@2026!')throw new Error('The identifier or password is incorrect for this portal. See README.md for the sample accounts.');storeSession(user);location.hash='/'+authRole.toLowerCase()+'/dashboard';return;}
    if(form.id==='activation-form'){form.reset();toast('Activation request preview complete. Email delivery and token verification require the backend.');return;}
    if(form.id==='reset-form'){if(values.password!==values.confirm)throw new Error('Passwords do not match.');form.reset();toast('Demo validation passed. Token verification requires the backend; no password was changed.');return;}
    if(form.id==='search-form'){view.search=values.search||'';view.mode=values.mode||'All';view.course=values.course||'All';render();return;}
    const user=currentUser();if(form.id!=='modal-form'&&!user)throw new Error('Your session expired. Sign in again.');
    if(form.id==='modal-form'&&modalSubmit){if(modalUserId&&currentUser()?.id!==modalUserId)throw new Error('Your session changed. Reopen the form after signing in.');const callback=modalSubmit;await callback(values,form);modal.close();render();return;}
    if(form.id==='profile-form'){if(!values.name.trim())throw new Error('Enter your full name.');if(db.users.some(u=>u.id!==user.id&&u.email.toLowerCase()===values.email.toLowerCase()))throw new Error('That email is already used by another demo account.');Object.assign(user,{name:values.name.trim(),email:values.email.trim(),phone:values.phone,bio:values.bio});audit('Updated profile');}
    save();render();toast('Saved in the demonstration.');
  }catch(error){if(errorBox)errorBox.textContent=error.message;else toast(error.message);}finally{if(submit)submit.disabled=false;}
});
window.addEventListener('hashchange',()=>{view={search:'',filter:'All',course:'All',mode:'All'};modal.close();render();window.scrollTo(0,0);$('#main')?.focus({preventScroll:true});});
window.addEventListener('storage',event=>{if(event.key===STORAGE){db=ensureCreatorAccounts(load());render();}});
setInterval(()=>{const timer=$('#shift-timer');if(timer&&db.shift)timer.textContent=elapsed(db.shift.clockIn);if(session&&!currentUser()){logout();location.hash='/login';toast('Your demo session ended. Sign in to continue.');}},1000);
render();

document.addEventListener('change',event=>{if(!['public-course','public-location'].includes(event.target.id))return;const course=$('#public-course').value,place=$('#public-location').value;let count=0;document.querySelectorAll('.home-job').forEach(card=>{card.hidden=!((course==='All'||card.dataset.courses.includes(course))&&(place==='All'||card.dataset.location.includes(place)));if(!card.hidden)count++;});$('#public-empty').hidden=count>0;});

document.addEventListener('dragover',event=>{if(event.target.closest('[data-action="document-upload"]'))event.preventDefault();});
document.addEventListener('drop',event=>{if(!event.target.closest('[data-action="document-upload"]'))return;event.preventDefault();try{if(currentUser()?.role!=='Student')throw new Error('Student portal required.');const files=event.dataTransfer.files;if(files.length!==1)throw new Error('Upload one document at a time.');validateUpload(files[0]);documentUpload();modal.querySelector('input[type="file"]').files=files;}catch(error){toast(error.message);}});
document.addEventListener('click',event=>{const drawer=$('#notice-drawer');if(drawer&&!event.target.closest('#notice-drawer')&&!event.target.closest('[data-action="notifications"]'))drawer.remove();});
